#!/usr/bin/env python3
import time
import subprocess

def get_clipboard():
    # Requires either xclip or xsel to be installed.
    for cmd in (["xclip", "-selection", "clipboard", "-o"],
                ["xsel", "--clipboard", "--output"]):
        try:
            return subprocess.check_output(cmd, stderr=subprocess.DEVNULL).decode("utf-8", "replace")
        except (FileNotFoundError, subprocess.CalledProcessError):
            pass
    raise RuntimeError("Need xclip or xsel installed to read clipboard on Linux.")

def main(interval=2.0):
    last = None
    while True:
        try:
            cur = get_clipboard()
            if cur != last:
                print(cur, flush=True)
                last = cur
        except Exception as e:
            print(f"[clipboard error] {e}", flush=True)
        time.sleep(interval)

if __name__ == "__main__":
    main(3.0)  # check every 3 seconds
```

This will print the clipboard contents whenever it changes. (It won’t work until `xclip` or `xsel` is available.)

