#!/usr/bin/env python3
import time
import subprocess

def get_clipboard():
    for cmd in (["xclip", "-selection", "clipboard", "-o"],
                ["xsel", "--clipboard", "--output"]):
        try:
            return subprocess.check_output(cmd, stderr=subprocess.DEVNULL).decode("utf-8", "replace")
        except (FileNotFoundError, subprocess.CalledProcessError):
            pass
    raise RuntimeError("Need xclip or xsel installed to read clipboard on Linux.")

def main(interval=3.0, duration=300.0, log_path="clipboard_history.log"):
    seen = set()
    unique = []

    start = time.time()
    while time.time() - start < duration:
        try:
            s = get_clipboard()
            if s not in seen:
                seen.add(s)
                unique.append(s)
                print(f"[new #{len(unique)}] {s!r}", flush=True)
        except Exception as e:
            print(f"[clipboard error] {e}", flush=True)

        time.sleep(interval)

    ts = time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime())
    with open(log_path, "a", encoding="utf-8") as f:
        f.write(f"=== Clipboard history session (UTC) {ts} ===\n")
        for i, s in enumerate(unique, 1):
            f.write(f"{i:04d}: {s}\n")
        f.write("\n")

    print(f"Saved {len(unique)} unique entries to {log_path}")

if __name__ == "__main__":
    main()  # logs after 5 minutes
```

This collects unique clipboard strings for 5 minutes, then appends them to `clipboard_history.log`.
